{
  "findings": [
    {
      "check_id": "CKV_GCP_14",
      "title": "Ensure all Cloud SQL database instance have backup configuration enabled",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "Backups are disabled for the database instance, which increases the risk of data loss in case of accidental deletion or corruption."
    },
    {
      "check_id": "CKV_GCP_6",
      "title": "Ensure all Cloud SQL database instance requires all incoming connections to use SSL",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "SSL is not required for incoming connections, which could expose sensitive data to interception during transit."
    },
    {
      "check_id": "CKV_GCP_54",
      "title": "Ensure PostgreSQL database 'log_lock_waits' flag is set to 'on'",
      "resource": "google_sql_database_instance.metadata_database",
      "severity": "MEDIUM",
      "explanation": "The 'log_lock_waits' flag is disabled, which prevents logging of lock wait events that can help in diagnosing performance issues."
    }
  ],
  "patched_code": "resource \"google_sql_database_instance\" \"metadata_database\" {\n  name             = \"digital-library-content-management-platform-db-metadata\"\n  database_version = \"POSTGRES_14\"\n  region           = var.region\n  deletion_protection = false\n  settings {\n    tier = \"db-f1-micro\"\n    backup_configuration {\n      enabled = true  # FIXED: Backup enabled\n    }\n    ip_configuration {\n      ipv4_enabled    = true\n      require_ssl     = true  # FIXED: SSL required\n    }\n    database_flags {\n      name  = \"log_lock_waits\"\n      value = \"on\"  # FIXED: Lock wait logging enabled\n    }\n  }\n}",
  "fix_summary": "Enabled backups to prevent data loss, enforced SSL for secure connections, and enabled 'log_lock_waits' flag to improve diagnostic capabilities."
}
